    bool do_causal_,
    const std::optional<array>& mask,
    const std::optional<array>& sinks,
    const std::optional<HylePageInfo>& page = std::nullopt) {
  using namespace mlx::steel;

  int bd = q.shape(-1);
  int bq = 64;
